)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	// One operation can zero out only the smallest distinct positive value.
	positive := map[int64]bool{}
	for i := 0; i < n; i++ {
		if v := nextInt(); v > 0 {
			positive[v] = true
		}
	}
	fmt.Println(len(positive))
